// Student Specific Components
import LUCWallet from '../profile/components/LUCWallet';
import ReferralDashboard from '../profile/components/ReferralDashboard';
import StudyMateHub from '../profile/components/StudyMateHub';
import ProjectSquadHub from '../profile/components/ProjectSquadHub';
import FoundersGear from '../profile/components/FoundersGear';
