import React, { useState, useEffect } from 'react';
import { supabaseService } from '../../../services/supabaseService';
import { useToast } from '../../../contexts/ToastContext';
import Icon from '../../../components/AppIcon';
import Button from '../../../components/ui/Button';
import { cn } from '../../../utils/cn';

const ProjectSquadHub = ({ userId }) => {
    const { addToast } = useToast();
    const [squads, setSquads] = useState([]);
    const [openMissions, setOpenMissions] = useState([]);
    const [isLoading, setIsLoading] = useState(true);
    const [isCreateModalOpen, setIsCreateModalOpen] = useState(false);
    const [showSubmitModal, setShowSubmitModal] = useState(null); // squad object
    const [invites, setInvites] = useState([]);

    useEffect(() => {
        if (userId) {
            fetchSquadData();
            fetchMissions();
        }
    }, [userId]);

    const fetchMissions = async () => {
        try {
            const missions = await supabaseService.getOpenMissions();
            setOpenMissions(missions);
        } catch (err) {
            console.error('Error fetching missions:', err);
        }
    };

    const fetchSquadData = async () => {
        setIsLoading(true);
        try {
            // 1. Fetch active squads
            const activeSquads = await supabaseService.getSquads(userId);
            setSquads(activeSquads);

            // 2. Fetch invites (placeholder for now)
            setInvites([]);

        } catch (error) {
            console.error('Error fetching squad data:', error);
        } finally {
            setIsLoading(false);
        }
    };

    const handleApply = async (squadId) => {
        try {
            await supabaseService.applyForSquad(userId, squadId, { 
                message: "I am ready to build and prove my work.",
                role: "Contributor"
            });
            addToast("Application sent to the Squad Leader!", "success");
        } catch (err) {
            addToast("Failed to apply.", "error");
        }
    };

    const handleSubmitProof = async (e) => {
        e.preventDefault();
        const formData = new FormData(e.target);
        const proofData = {
            squad_id: showSubmitModal.id,
            url: formData.get('url'),
            description: formData.get('description')
        };

        try {
            // Placeholder for squad output submission service call
            console.log("Submitting Squad Proof:", proofData);
            addToast("Squad Proof submitted for Admin verification!", "success");
            setShowSubmitModal(null);
        } catch (err) {
            addToast("Submission failed.", "error");
        }
    };

    const handleCreateSquad = async (e) => {
        e.preventDefault();
        const formData = new FormData(e.target);
        const squadData = {
            name: formData.get('name'),
            description: formData.get('description'),
            mission: formData.get('mission'),
            is_public: formData.get('is_public') === 'on'
        };

        try {
            await supabaseService.createSquad(userId, squadData);
            addToast('Squad created successfully!', 'success');
            setIsCreateModalOpen(false);
            fetchSquadData();
        } catch (err) {
            addToast('Failed to create squad', 'error');
        }
    };

    if (isLoading) return <div className="animate-pulse space-y-6"><div className="h-64 bg-muted rounded-[3rem]" /><div className="grid grid-cols-2 gap-6"><div className="h-48 bg-muted rounded-[2.5rem]" /><div className="h-48 bg-muted rounded-[2.5rem]" /></div></div>;

    return (
        <div className="space-y-12">
            {/* Project Hero */}
            <div className="bg-gradient-to-br from-emerald-900 to-slate-950 rounded-[3rem] p-10 md:p-14 text-white relative overflow-hidden shadow-2xl border border-white/5">
                <div className="absolute top-0 right-0 -mr-20 -mt-20 w-96 h-96 bg-emerald-500/10 rounded-full blur-[120px]" />
                <div className="absolute bottom-0 left-0 -ml-20 -mb-20 w-96 h-96 bg-primary/10 rounded-full blur-[120px]" />
                
                <div className="relative z-10 grid grid-cols-1 lg:grid-cols-2 gap-12 items-center">
                    <div className="text-center lg:text-left">
                        <div className="inline-flex items-center gap-2 px-4 py-2 bg-emerald-500/10 border border-emerald-500/20 rounded-full mb-8 backdrop-blur-md">
                            <Icon name="Rocket" size={16} className="text-emerald-400" />
                            <span className="text-[10px] font-black uppercase tracking-[0.3em] text-emerald-400">Elite Project Squads</span>
                        </div>
                        <h2 className="text-4xl md:text-6xl font-black italic tracking-tighter leading-[0.9] mb-8">
                            Build. Launch. <br />
                            <span className="text-emerald-400">Collaborate.</span>
                        </h2>
                        <p className="text-lg text-slate-300 font-medium mb-10 max-w-xl leading-relaxed">
                            Form high-impact project groups with fellow scholars. Turn your learning into real-world applications and dominate the Hall of Fame.
                        </p>
                        <div className="flex flex-wrap gap-4 justify-center lg:justify-start">
                            <Button 
                                variant="secondary" 
                                size="xl" 
                                className="font-black italic px-10 shadow-2xl shadow-secondary/20"
                                onClick={() => setIsCreateModalOpen(true)}
                            >
                                START A SQUAD
                            </Button>
                            <Button 
                                variant="ghost" 
                                className="text-white hover:bg-white/5 font-bold"
                                onClick={() => addToast('Mission Board is now LIVE below!', 'info')}
                            >
                                BROWSE OPEN MISSIONS
                            </Button>
                        </div>
                    </div>
                    
                    <div className="hidden lg:flex justify-end relative">
                        <div className="w-64 h-64 bg-emerald-500/20 rounded-[4rem] border-2 border-emerald-500/30 flex items-center justify-center rotate-12 relative z-10 group hover:rotate-0 transition-transform duration-700">
                            <Icon name="Users" size={80} className="text-emerald-400 group-hover:scale-110 transition-transform" />
                        </div>
                        <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 w-80 h-80 bg-white/5 rounded-full blur-3xl" />
                    </div>
                </div>
            </div>

            {/* Create Squad Modal */}
            {isCreateModalOpen && (
                <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-slate-950/80 backdrop-blur-md">
                    <div className="bg-slate-900 border border-white/10 rounded-[3rem] p-8 md:p-12 max-w-2xl w-full shadow-2xl relative animate-in zoom-in-95 duration-300">
                        <button onClick={() => setIsCreateModalOpen(false)} className="absolute top-6 right-6 text-slate-400 hover:text-white">
                            <Icon name="X" size={24} />
                        </button>
                        <h3 className="text-3xl font-black text-white italic mb-8 tracking-tighter">Forge a New <span className="text-emerald-400">Squad</span></h3>
                        <form onSubmit={handleCreateSquad} className="space-y-6">
                            <div className="space-y-2">
                                <label className="text-[10px] font-black uppercase tracking-widest text-emerald-400">Squad Name</label>
                                <input name="name" required className="w-full bg-white/5 border border-white/10 rounded-2xl p-4 text-white focus:ring-2 focus:ring-emerald-500 outline-none" placeholder="e.g. AI Ethics Research Group" />
                            </div>
                            <div className="space-y-2">
                                <label className="text-[10px] font-black uppercase tracking-widest text-emerald-400">The Mission</label>
                                <select name="mission" required className="w-full bg-slate-900 border border-white/10 rounded-2xl p-4 text-white focus:ring-2 focus:ring-emerald-500 outline-none">
                                    <option value="">Select a mission type...</option>
                                    <option value="Tech Development">Tech Development</option>
                                    <option value="Social Impact">Social Impact</option>
                                    <option value="Research">Research</option>
                                    <option value="Design Mastery">Design Mastery</option>
                                    <option value="Business Strategy">Business Strategy</option>
                                    <option value="Summer Camp Build">Summer Camp Build</option>
                                </select>
                            </div>
                            <div className="space-y-2">
                                <label className="text-[10px] font-black uppercase tracking-widest text-emerald-400">Description</label>
                                <textarea name="description" required className="w-full bg-white/5 border border-white/10 rounded-2xl p-4 text-white focus:ring-2 focus:ring-emerald-500 outline-none min-h-[100px]" placeholder="Describe the goal of this squad..." />
                            </div>
                            <div className="flex items-center gap-3 p-4 bg-white/5 rounded-2xl border border-white/10">
                                <input type="checkbox" name="is_public" id="is_public" className="w-5 h-5 rounded accent-emerald-500" defaultChecked />
                                <label htmlFor="is_public" className="text-sm text-slate-300 font-bold">Public Mission (Allow others to apply)</label>
                            </div>
                            <Button type="submit" variant="secondary" className="w-full py-6 font-black italic shadow-xl shadow-emerald-500/20">LAUNCH MISSION</Button>
                        </form>
                    </div>
                </div>
            )}

            {/* Pending Invites */}
            {invites.length > 0 && (
                <div className="bg-emerald-500/5 border border-emerald-500/10 rounded-[2.5rem] p-8">
                    <h3 className="text-xs font-black uppercase tracking-widest text-emerald-500 mb-6 flex items-center gap-2">
                        <Icon name="Mail" size={16} />
                        Squad Invitations
                    </h3>
                    <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                        {invites.map(invite => (
                            <div key={invite.id} className="bg-white/5 backdrop-blur-xl p-6 rounded-3xl border border-white/10 flex flex-col items-center text-center">
                                <Icon name="Briefcase" size={32} className="text-emerald-400 mb-4" />
                                <h4 className="font-black text-white italic mb-2">{invite.squad?.name}</h4>
                                <p className="text-[10px] text-slate-400 uppercase tracking-widest mb-6 font-bold">Invited as {invite.role || 'Member'}</p>
                                <div className="flex gap-3 w-full">
                                    <button className="flex-1 py-3 bg-emerald-500 text-white rounded-2xl text-[10px] font-black uppercase hover:bg-emerald-600 transition-colors">Accept</button>
                                    <button className="flex-1 py-3 bg-white/5 text-slate-400 rounded-2xl text-[10px] font-black uppercase hover:bg-white/10 transition-colors">Ignore</button>
                                </div>
                            </div>
                        ))}
                    </div>
                </div>
            )}

            <div className="grid grid-cols-1 xl:grid-cols-3 gap-10">
                {/* Active Squads */}
                <div className="xl:col-span-2 space-y-8">
                    <div className="flex items-center justify-between px-2">
                        <h3 className="font-black italic text-2xl uppercase tracking-tighter text-white">Active Squads</h3>
                        <div className="flex items-center gap-2 px-3 py-1 bg-white/5 rounded-lg border border-white/10">
                            <div className="w-2 h-2 bg-emerald-500 rounded-full animate-pulse" />
                            <span className="text-[10px] font-bold text-slate-400 uppercase">{squads.length} Active Missions</span>
                        </div>
                    </div>

                    <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                        {squads.length === 0 ? (
                            <div className="md:col-span-2 p-20 border-2 border-dashed border-white/5 rounded-[3rem] text-center bg-white/[0.02] flex flex-col items-center justify-center">
                                <div className="w-20 h-20 bg-white/5 rounded-3xl flex items-center justify-center mb-6">
                                    <Icon name="Plus" size={40} className="text-slate-600" />
                                </div>
                                <h4 className="font-black text-white italic text-lg mb-2">No Squads Joined</h4>
                                <p className="text-slate-500 font-medium max-w-xs mx-auto">Start a new project or join an existing mission to earn bonus rewards.</p>
                                <Button variant="outline" className="mt-6 border-white/10 text-white" onClick={() => setIsCreateModalOpen(true)}>Create Your First Squad</Button>
                            </div>
                        ) : (
                            squads.map(squad => (
                                <div key={squad.id} className="group bg-white/5 hover:bg-white/[0.08] border border-white/10 rounded-[2.5rem] p-8 transition-all duration-500 hover:-translate-y-1">
                                    <div className="flex items-center justify-between mb-6">
                                        <div className="px-3 py-1 bg-emerald-500/10 rounded-lg text-[9px] font-black uppercase tracking-widest text-emerald-400 border border-emerald-500/20">
                                            {squad.mission || 'General Project'}
                                        </div>
                                        <div className="flex -space-x-2">
                                            {[1, 2, 3].map(i => (
                                                <img key={i} src={`https://i.pravatar.cc/100?u=${squad.id + i}`} className="w-8 h-8 rounded-full border-2 border-slate-900 object-cover" />
                                            ))}
                                            <div className="w-8 h-8 rounded-full bg-slate-800 border-2 border-slate-900 flex items-center justify-center text-[8px] font-black text-white">
                                                +{squad.members_count || 1}
                                            </div>
                                        </div>
                                    </div>
                                    <h4 className="text-2xl font-black text-white italic mb-3 tracking-tighter">{squad.name}</h4>
                                    <p className="text-slate-400 text-sm font-medium mb-8 leading-relaxed line-clamp-2">
                                        {squad.description}
                                    </p>
                                    <div className="flex items-center justify-between pt-6 border-t border-white/5">
                                        <div className="flex items-center gap-2">
                                            <Icon name="Target" size={14} className="text-secondary" />
                                            <span className="text-[10px] font-black uppercase tracking-widest text-slate-500">Live Workspace</span>
                                        </div>
                                        <Button 
                                            variant="ghost" 
                                            size="sm" 
                                            className="text-emerald-400 hover:text-emerald-300 font-black italic"
                                            onClick={() => setShowSubmitModal(squad)}
                                        >
                                            SUBMIT MISSION PROOF
                                        </Button>
                                    </div>
                                </div>
                            ))
                        )}
                    </div>
                </div>

                {/* Create Squad Output Modal */}
                {showSubmitModal && (
                    <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-slate-950/80 backdrop-blur-md">
                        <div className="bg-slate-900 border border-white/10 rounded-[3rem] p-8 md:p-12 max-w-2xl w-full shadow-2xl relative animate-in zoom-in-95 duration-300">
                            <button onClick={() => setShowSubmitModal(null)} className="absolute top-6 right-6 text-slate-400 hover:text-white">
                                <Icon name="X" size={24} />
                            </button>
                            <h3 className="text-3xl font-black text-white italic mb-4 tracking-tighter">Submit <span className="text-emerald-400">Squad Proof</span></h3>
                            <p className="text-sm text-slate-400 mb-8 font-medium">Verify your squad's output to unlock collective rewards and Hall of Fame recognition.</p>
                            
                            <form onSubmit={handleSubmitProof} className="space-y-6">
                                <div className="space-y-2">
                                    <label className="text-[10px] font-black uppercase tracking-widest text-emerald-400">Project URL (GitHub / Figma / Live)</label>
                                    <input name="url" required className="w-full bg-white/5 border border-white/10 rounded-2xl p-4 text-white focus:ring-2 focus:ring-emerald-500 outline-none" placeholder="https://github.com/your-squad/project" />
                                </div>
                                <div className="space-y-2">
                                    <label className="text-[10px] font-black uppercase tracking-widest text-emerald-400">Brief Summary of Contribution</label>
                                    <textarea name="description" required className="w-full bg-white/5 border border-white/10 rounded-2xl p-4 text-white focus:ring-2 focus:ring-emerald-500 outline-none min-h-[100px]" placeholder="Explain exactly what the squad built..." />
                                </div>
                                <div className="p-4 bg-emerald-500/10 border border-emerald-500/20 rounded-2xl flex items-center gap-4">
                                    <div className="w-10 h-10 rounded-full bg-emerald-500/20 flex items-center justify-center text-emerald-400">
                                        <Icon name="ShieldCheck" size={20} />
                                    </div>
                                    <p className="text-[10px] font-black uppercase text-emerald-400 leading-tight">Admin verification required. Results will be reflected in the Venture Portfolio.</p>
                                </div>
                                <Button type="submit" variant="secondary" className="w-full py-6 font-black italic shadow-xl shadow-emerald-500/20">VERIFY OUTPUT</Button>
                            </form>
                        </div>
                    </div>
                )}

                {/* Squad Stats & Opportunities */}
                <div className="space-y-10">
                    <div className="bg-white/5 border border-white/10 rounded-[3rem] p-8 shadow-2xl">
                        <h3 className="font-black italic text-xl uppercase tracking-tighter text-white mb-6">Launchpad</h3>
                        <p className="text-[10px] font-bold text-slate-500 uppercase mb-8">Public missions seeking talent</p>
                        <div className="space-y-6">
                            {openMissions.length === 0 ? (
                                <p className="text-xs text-slate-500 italic text-center py-10">No public missions available right now.</p>
                            ) : (
                                openMissions.map(mission => (
                                    <div key={mission.id} className="p-5 bg-white/5 rounded-2xl border border-white/10 group hover:border-emerald-500/50 transition-all">
                                        <div className="flex items-center gap-4 mb-4">
                                            <div className="w-10 h-10 bg-emerald-500/20 rounded-xl flex items-center justify-center">
                                                <Icon name="Zap" size={18} className="text-emerald-400" />
                                            </div>
                                            <div className="min-w-0">
                                                <p className="text-xs font-black text-white italic truncate">{mission.name}</p>
                                                <p className="text-[9px] font-bold text-slate-500 uppercase tracking-tighter truncate">Goal: {mission.mission || 'Building'}</p>
                                            </div>
                                        </div>
                                        <Button 
                                            size="sm" 
                                            className="w-full bg-emerald-500 hover:bg-emerald-600 text-[10px] font-black uppercase rounded-xl"
                                            onClick={() => handleApply(mission.id)}
                                        >
                                            Apply to Join
                                        </Button>
                                    </div>
                                ))
                            )}
                        </div>
                    </div>

                    <div className="p-8 bg-gradient-to-br from-secondary/10 to-transparent border border-secondary/20 rounded-[3rem]">
                        <h4 className="text-sm font-black italic mb-3 uppercase text-secondary">The Squad Bonus</h4>
                        <p className="text-xs font-medium text-slate-400 leading-relaxed">
                            Complete a Squad Mission and unlock the <span className="text-secondary font-black">LEGACY BADGE</span> plus a shared <span className="text-secondary font-black">+100 LUC</span> bonus!
                        </p>
                    </div>
                </div>
            </div>
        </div>
    );
};

export default ProjectSquadHub;
