import React, { useState, useEffect } from 'react';
import { supabaseService } from '../../../services/supabaseService';
import { useToast } from '../../../contexts/ToastContext';
import Icon from '../../../components/AppIcon';
import Button from '../../../components/ui/Button';

const StudyMateHub = ({ userId }) => {
    const { addToast } = useToast();
    const [mates, setMates] = useState([]);
    const [recommended, setRecommended] = useState([]);
    const [requests, setRequests] = useState([]);
    const [isLoading, setIsLoading] = useState(true);

    useEffect(() => {
        if (userId) {
            fetchMateData();
        }
    }, [userId]);

    const fetchMateData = async () => {
        setIsLoading(true);
        try {
            // 1. Fetch current mates & requests
            const { data: mateData, error: mateError } = await supabaseService.supabase
                .from('study_mates')
                .select(`
                    *,
                    requester:requester_id (id, full_name, avatar_url),
                    receiver:receiver_id (id, full_name, avatar_url)
                `)
                .or(`requester_id.eq.${userId},receiver_id.eq.${userId}`);

            if (mateError) throw mateError;

            const active = mateData.filter(m => m.status === 'active');
            const pending = mateData.filter(m => m.status === 'pending' && m.receiver_id === userId);
            
            setMates(active);
            setRequests(pending);

            // 2. Fetch recommended (students in same courses, but not yet mates)
            // For now, we'll just fetch a few active students as a placeholder
            const { data: recData, error: recError } = await supabaseService.supabase
                .from('enrollments')
                .select('user_id, profiles:user_id(id, full_name, avatar_url)')
                .neq('user_id', userId)
                .limit(30);

            if (!recError && recData) {
                // Deduplicate users
                const uniqueUsers = Array.from(new Map(recData.filter(r => r.profiles).map(r => [r.profiles.id, r.profiles])).values());
                // Filter out those who are already mates or requested
                const mateIds = mateData.map(m => m.requester_id === userId ? m.receiver_id : m.requester_id);
                setRecommended(uniqueUsers.filter(r => !mateIds.includes(r.id)).slice(0, 5));
            }

        } catch (error) {
            console.error('Error fetching study mate data:', error);
            addToast('Failed to load study mates', 'error');
        } finally {
            setIsLoading(false);
        }
    };

    const sendRequest = async (targetId) => {
        try {
            const { error } = await supabaseService.supabase
                .from('study_mates')
                .insert([{ requester_id: userId, receiver_id: targetId, status: 'pending' }]);
            
            if (error) throw error;
            addToast('Study request sent!', 'success');
            fetchMateData();
        } catch (error) {
            addToast('Could not send request', 'error');
        }
    };

    const handleRequest = async (requestId, status) => {
        try {
            const { error } = await supabaseService.supabase
                .from('study_mates')
                .update({ status })
                .eq('id', requestId);
            
            if (error) throw error;
            addToast(`Request ${status}`, 'success');
            fetchMateData();
        } catch (error) {
            addToast('Failed to update request', 'error');
        }
    };

    if (isLoading) return <div className="animate-pulse space-y-4"><div className="h-48 bg-muted rounded-[2rem]" /><div className="h-64 bg-muted rounded-[2rem]" /></div>;

    return (
        <div className="space-y-10">
            {/* Header / Hero */}
            <div className="bg-gradient-to-br from-indigo-900 to-slate-900 rounded-[2.5rem] p-10 text-white relative overflow-hidden shadow-2xl border border-white/5">
                <div className="absolute top-0 right-0 -mr-16 -mt-16 w-80 h-80 bg-primary/10 rounded-full blur-[100px]" />
                <div className="relative z-10 grid grid-cols-1 md:grid-cols-2 gap-8 items-center">
                    <div>
                        <div className="inline-flex items-center gap-2 px-3 py-1 bg-white/10 rounded-lg text-[10px] font-black uppercase tracking-widest mb-4">
                            <Icon name="Users" size={12} />
                            <span>Academic Collaboration</span>
                        </div>
                        <h2 className="text-4xl font-black italic tracking-tighter leading-tight mb-4">
                            Find Your <span className="text-secondary">Study Mate.</span>
                        </h2>
                        <p className="text-slate-300 font-medium mb-8 max-w-sm">
                            Learn 2x faster by partnering with fellow scholars. Share progress, hold each other accountable, and earn bonus LUC credits.
                        </p>
                    </div>
                    <div className="flex justify-center md:justify-end">
                        <div className="w-24 h-24 bg-secondary/20 rounded-[2rem] flex items-center justify-center border border-secondary/30">
                            <Icon name="Handshake" size={48} className="text-secondary" />
                        </div>
                    </div>
                </div>
            </div>

            {/* Pending Requests */}
            {requests.length > 0 && (
                <div className="bg-amber-500/5 border border-amber-500/20 rounded-[2rem] p-6">
                    <h3 className="text-xs font-black uppercase tracking-widest text-amber-600 mb-4 flex items-center gap-2">
                        <Icon name="BellRing" size={14} />
                        Study Requests
                    </h3>
                    <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-4">
                        {requests.map(req => (
                            <div key={req.id} className="bg-white dark:bg-slate-900 p-4 rounded-2xl border border-border shadow-sm flex flex-col items-center text-center">
                                <img src={req.requester?.avatar_url || `https://ui-avatars.com/api/?name=${req.requester?.full_name}`} className="w-12 h-12 rounded-full mb-3" />
                                <p className="font-bold text-sm mb-1">{req.requester?.full_name}</p>
                                <p className="text-[10px] text-muted-foreground mb-4 uppercase font-black">wants to study with you</p>
                                <div className="flex gap-2 w-full mt-auto">
                                    <button 
                                        onClick={() => handleRequest(req.id, 'active')}
                                        className="flex-1 py-2 bg-emerald-500 text-white rounded-xl text-[10px] font-black uppercase hover:bg-emerald-600"
                                    >
                                        Accept
                                    </button>
                                    <button 
                                        onClick={() => handleRequest(req.id, 'declined')}
                                        className="flex-1 py-2 bg-muted text-muted-foreground rounded-xl text-[10px] font-black uppercase"
                                    >
                                        Decline
                                    </button>
                                </div>
                            </div>
                        ))}
                    </div>
                </div>
            )}

            <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
                {/* Active Mates List */}
                <div className="lg:col-span-2 space-y-6">
                    <div className="flex items-center justify-between px-2">
                        <h3 className="font-black italic text-lg uppercase tracking-tighter">My Study Partners</h3>
                        <span className="text-[10px] font-bold text-muted-foreground uppercase">{mates.length} Connected</span>
                    </div>

                    <div className="grid grid-cols-1 gap-4">
                        {mates.length === 0 ? (
                            <div className="p-12 border-2 border-dashed border-border rounded-[2.5rem] text-center opacity-30">
                                <Icon name="UserPlus" size={40} className="mx-auto mb-4" />
                                <p className="font-bold text-sm uppercase">No partners yet.</p>
                            </div>
                        ) : (
                            mates.map(mate => {
                                const partner = mate.requester_id === userId ? mate.receiver : mate.requester;
                                return (
                                    <div key={mate.id} className="bg-card border border-border rounded-3xl p-6 flex items-center justify-between group hover:border-primary/50 transition-all">
                                        <div className="flex items-center gap-4">
                                            <div className="relative">
                                                <img src={partner.avatar_url || `https://ui-avatars.com/api/?name=${partner.full_name}`} className="w-14 h-14 rounded-2xl object-cover" />
                                                <div className="absolute -bottom-1 -right-1 w-4 h-4 bg-emerald-500 border-2 border-white dark:border-slate-900 rounded-full" />
                                            </div>
                                            <div>
                                                <h4 className="font-black text-base">{partner.full_name}</h4>
                                                <div className="flex items-center gap-3 mt-1">
                                                    <span className="text-[10px] font-bold text-muted-foreground uppercase tracking-widest">Master Scholar</span>
                                                    <span className="w-1 h-1 rounded-full bg-border" />
                                                    <span className="text-[10px] font-bold text-emerald-500 italic">Connected</span>
                                                </div>
                                            </div>
                                        </div>
                                        <div className="flex gap-2">
                                            <Button variant="ghost" size="sm" className="rounded-xl">
                                                <Icon name="MessageSquare" size={18} />
                                            </Button>
                                            <Button variant="outline" size="sm" className="rounded-xl border-border hover:bg-muted text-[10px] font-black uppercase">
                                                View Progress
                                            </Button>
                                        </div>
                                    </div>
                                );
                            })
                        )}
                    </div>
                </div>

                {/* Recommendations Sidebar */}
                <div className="space-y-6">
                    <div className="px-2">
                        <h3 className="font-black italic text-lg uppercase tracking-tighter">Recommended</h3>
                        <p className="text-[10px] font-bold text-muted-foreground uppercase mt-1">Scholars in your courses</p>
                    </div>

                    <div className="space-y-4">
                        {recommended.map(rec => (
                            <div key={rec.id} className="bg-card border border-border rounded-2xl p-4 flex items-center justify-between hover:bg-muted/30 transition-colors">
                                <div className="flex items-center gap-3">
                                    <img src={rec.avatar_url || `https://ui-avatars.com/api/?name=${rec.full_name}`} className="w-10 h-10 rounded-xl" />
                                    <div className="max-w-[100px]">
                                        <p className="font-bold text-xs truncate">{rec.full_name}</p>
                                        <p className="text-[9px] text-muted-foreground uppercase font-medium">95% Match</p>
                                    </div>
                                </div>
                                <button 
                                    onClick={() => sendRequest(rec.id)}
                                    className="p-2 bg-primary/10 text-primary rounded-xl hover:bg-primary hover:text-white transition-all"
                                >
                                    <Icon name="UserPlus" size={16} />
                                </button>
                            </div>
                        ))}
                    </div>

                    <div className="p-6 bg-secondary/5 border border-secondary/20 rounded-3xl">
                        <h4 className="text-xs font-black italic mb-2 uppercase text-secondary">The Mastery Pact</h4>
                        <p className="text-[10px] font-medium text-muted-foreground leading-relaxed">
                            Finish any course with your mate and both of you will receive a <span className="text-secondary font-bold font-black">+20 LUC</span> bonus!
                        </p>
                    </div>
                </div>
            </div>
        </div>
    );
};

export default StudyMateHub;
