import React, { useState } from 'react';
import Modal from '../../../components/ui/Modal';
import Button from '../../../components/ui/Button';
import Icon from '../../../components/AppIcon';
import { supabaseService } from '../../../services/supabaseService';
import { useToast } from '../../../contexts/ToastContext';
import { formatLuc } from '../../../utils/currencyUtils';

const SendCreditsModal = ({ isOpen, onClose, senderId, currentBalance, onTransferSuccess }) => {
    const { addToast } = useToast();
    const [recipientEmail, setRecipientEmail] = useState('');
    const [amount, setAmount] = useState('');
    const [purpose, setPurpose] = useState('Research Assistance');
    const [isLoading, setIsLoading] = useState(false);

    const handleSubmit = async (e) => {
        e.preventDefault();
        
        const numericAmount = parseFloat(amount);
        if (isNaN(numericAmount) || numericAmount <= 0) {
            addToast("Please enter a valid amount", "warning");
            return;
        }

        if (numericAmount > currentBalance) {
            addToast("Insufficient balance", "error");
            return;
        }

        setIsLoading(true);
        try {
            const result = await supabaseService.transferCredits(
                senderId,
                recipientEmail.trim().toLowerCase(),
                numericAmount,
                purpose
            );

            if (result.success) {
                addToast(`Successfully sent ${formatLuc(numericAmount)}!`, "success");
                onTransferSuccess();
                onClose();
                // Reset form
                setRecipientEmail('');
                setAmount('');
                setPurpose('Research Assistance');
            } else {
                addToast(result.message || "Transfer failed", "error");
            }
        } catch (error) {
            console.error("Transfer error:", error);
            addToast("A database error occurred during transfer", "error");
        } finally {
            setIsLoading(false);
        }
    };

    const purposes = [
        "Research Assistance",
        "Project Collaboration",
        "Concept Mastery / Tutoring",
        "Resource Sharing",
        "Community Support"
    ];

    return (
        <Modal
            isOpen={isOpen}
            onClose={onClose}
            title="Send LUC Credits"
            size="md"
        >
            <form onSubmit={handleSubmit} className="space-y-6">
                {/* Header info */}
                <div className="p-4 bg-indigo-500/10 border border-indigo-500/20 rounded-2xl flex items-center gap-4">
                    <div className="w-12 h-12 rounded-2xl bg-indigo-500 text-white flex items-center justify-center">
                        <Icon name="Send" size={24} />
                    </div>
                    <div>
                        <p className="text-xs font-bold text-indigo-500 uppercase tracking-widest">Available Balance</p>
                        <p className="text-xl font-black text-foreground">{formatLuc(currentBalance)}</p>
                    </div>
                </div>

                {/* Recipient */}
                <div className="space-y-2">
                    <label className="text-xs font-black uppercase tracking-widest text-muted-foreground ml-1">Recipient Email</label>
                    <div className="relative">
                        <Icon name="Mail" size={18} className="absolute left-4 top-1/2 -translate-y-1/2 text-muted-foreground" />
                        <input
                            type="email"
                            required
                            placeholder="scholar@lucacademy.com"
                            value={recipientEmail}
                            onChange={(e) => setRecipientEmail(e.target.value)}
                            className="w-full h-14 pl-12 pr-4 bg-muted/50 border-2 border-transparent focus:border-primary/20 rounded-2xl outline-none transition-all font-medium"
                        />
                    </div>
                </div>

                {/* Amount */}
                <div className="space-y-2">
                    <label className="text-xs font-black uppercase tracking-widest text-muted-foreground ml-1">Amount to Send</label>
                    <div className="relative">
                        <Icon name="Coins" size={18} className="absolute left-4 top-1/2 -translate-y-1/2 text-muted-foreground" />
                        <input
                            type="number"
                            required
                            min="1"
                            placeholder="0.00"
                            value={amount}
                            onChange={(e) => setAmount(e.target.value)}
                            className="w-full h-14 pl-12 pr-4 bg-muted/50 border-2 border-transparent focus:border-primary/20 rounded-2xl outline-none transition-all font-black text-lg"
                        />
                    </div>
                </div>

                {/* Purpose */}
                <div className="space-y-2">
                    <label className="text-xs font-black uppercase tracking-widest text-muted-foreground ml-1">Purpose of Transfer</label>
                    <select
                        value={purpose}
                        onChange={(e) => setPurpose(e.target.value)}
                        className="w-full h-14 px-4 bg-muted/50 border-2 border-transparent focus:border-primary/20 rounded-2xl outline-none transition-all font-medium appearance-none cursor-pointer"
                    >
                        {purposes.map(p => (
                            <option key={p} value={p}>{p}</option>
                        ))}
                    </select>
                </div>

                <div className="p-4 bg-amber-500/5 border border-amber-500/20 rounded-2xl">
                    <p className="text-[10px] text-amber-600 font-bold leading-relaxed">
                        <Icon name="AlertCircle" size={10} className="inline mr-1" />
                        Note: Credits cannot be used for assistance with graded assessments or exams. All transfers are logged for academic integrity monitoring.
                    </p>
                </div>

                <Button
                    type="submit"
                    fullWidth
                    loading={isLoading}
                    className="h-16 text-lg font-black italic bg-indigo-600 hover:bg-indigo-700 text-white shadow-xl shadow-indigo-600/20 rounded-2xl"
                >
                    INITIATE TRANSFER
                </Button>
            </form>
        </Modal>
    );
};

export default SendCreditsModal;
